        let t = Math.imul(rnd ^ (rnd >>> 15), 1 | rnd);
        t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
        const v = ((t ^ (t >>> 14)) >>> 0) / 4294967296;
